import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Introducción: encuentra tu lugar en un mundo vivo","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md"}'),r={name:"es/guide/introduction.md"};function t(s,e,d,l,c,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<p><span id="introduction-a-living-world-shaped-by-its-people"></span><span id="a-world-that-can-change-your-plans"></span><span id="combat-with-room-to-grow"></span><span id="knowledge-is-useful-in-the-moment"></span><span id="crafts-belong-to-adventurers"></span><span id="discover-your-specialty"></span><span id="magic-is-learned-and-prepared"></span><span id="items-with-a-story"></span><span id="more-than-one-endgame"></span></p><h1 id="introduction-make-your-place-in-a-living-world" tabindex="-1">Introducción: encuentra tu lugar en un mundo vivo <a class="header-anchor" href="#introduction-make-your-place-in-a-living-world" aria-label="Enlace permanente a &quot;Introducción: encuentra tu lugar en un mundo vivo&quot;">​</a></h1><p><strong>Estado:</strong> Dirección con estado Propuesto y bases con estado Aceptado · Las funciones descritas pueden no estar disponibles todavía.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Desarrolla un personaje mediante <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidades</a>, descubrimientos y decisiones dentro del mundo.</li><li>Combate con el ritmo manual de <a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Modern</a> o los ataques automáticos de <a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Legacy</a>; el conocimiento ayuda a elegir.</li><li>La artesanía, la magia, el comercio y la exploración ofrecen metas más allá de una única escala de poder.</li></ul><p>Syrolands reimagina el sandbox de Ultima Online alrededor de tres ideas: el mundo debe reaccionar a los jugadores, el conocimiento debe importar y la ejecución del jugador debe contar junto a la habilidad del personaje. No necesitas haber jugado a UO para seguir estas ideas.</p><h2 id="coming-from-ultima-online" tabindex="-1">¿Vienes de Ultima Online? <a class="header-anchor" href="#coming-from-ultima-online" aria-label="Enlace permanente a &quot;¿Vienes de Ultima Online?&quot;">​</a></h2><p>Estas comparaciones describen tradiciones conocidas de UO, no todas sus expansiones o servidores. Las habilidades de arma y las maestrías posteriores se identifican cuando corresponde; «UO clásico» no significa que todos esos sistemas coexistieran.</p><table tabindex="0"><thead><tr><th>Idea conocida de UO</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Personajes basados en habilidades y combinaciones 7×GM</td><td>Conservar los personajes por habilidades; una combinación útil no necesita seguir una única receta 7×GM</td></tr><tr><td>Un presupuesto de unos 700 puntos de habilidad, con límites según la época</td><td>Mantener unos 700 como dirección del diseño, con elecciones que tengan un coste</td></tr><tr><td>Golpes automáticos con armas</td><td>Conservar <a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Legacy</a>; <a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Modern</a> permite elegir cuándo comprometerse con una acción</td></tr><tr><td>Efectos especiales de armas y, en el UO posterior, habilidades seleccionables</td><td>Aprender <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a> y desarrollar <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> con las opciones que utilizas</td></tr><tr><td>Personajes dedicados a fabricar como estilo de juego habitual</td><td>Hacer que las profesiones sean útiles en aventuras, talleres y comercio</td></tr><tr><td>Un libro que contiene los hechizos que puedes lanzar</td><td>Separar conocimiento permanente, práctica y <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a> preparada</td></tr><tr><td>Riesgo de saqueo al estilo de Felucca</td><td>Conservar el riesgo sobre el equipo; el conocimiento aprendido sobrevive a la muerte, con excepciones de objetos aún por resolver</td></tr><tr><td>Recolección de recursos y objetos establecidos en el mundo</td><td>Permitir que ciertos árboles, materiales y terrenos alteren rutas y conflictos</td></tr><tr><td>Artesanía excepcional y equipo valioso</td><td>Dar a la calidad <a href="/Syrolands-Public/es/guide/glossary.html#handling">manejo</a>, <a href="/Syrolands-Public/es/guide/glossary.html#consistency">consistencia</a>, integridad, rasgos e historia; los <a href="/Syrolands-Public/es/guide/items/item-quality.html">Masterworks</a> siguen siendo raros</td></tr></tbody></table><h2 id="a-living-sandbox" tabindex="-1">Un sandbox vivo <a class="header-anchor" href="#a-living-sandbox" aria-label="Enlace permanente a &quot;Un sandbox vivo&quot;">​</a></h2><p>Un árbol puede ser algo más que una fuente de troncos: talarlo podría bloquear un paso estrecho, abrir una ruta o cambiar una posición defensiva. Los materiales, el clima y las herramientas deberían ayudarte a interpretar las posibilidades. Las zonas protegidas y la recuperación aún necesitan límites; no se promete que cualquier objeto pueda destruirse.</p><h2 id="fight-don-t-just-watch-your-character-fight" tabindex="-1">Lucha, no te limites a mirar cómo lucha tu personaje <a class="header-anchor" href="#fight-don-t-just-watch-your-character-fight" aria-label="Enlace permanente a &quot;Lucha, no te limites a mirar cómo lucha tu personaje&quot;">​</a></h2><p>Modern Combat es la dirección experimental preferida: decide cuándo actuar, calcula el <a href="/Syrolands-Public/es/guide/combat/reach-and-spacing.html">alcance</a> y deja margen para recuperarte. La cadencia automática Legacy sigue siendo una alternativa compatible. <a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Stamina</a>, Special Attacks, <a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a>, el estado de las extremidades y el equipo crean decisiones; Anatomy y otras habilidades informativas ayudan a interpretarlas. Importan tanto el momento elegido como la experiencia del personaje.</p><h2 id="learn-the-world-instead-of-following-a-fixed-build" tabindex="-1">Aprende el mundo en lugar de seguir una combinación fija <a class="header-anchor" href="#learn-the-world-instead-of-following-a-fixed-build" aria-label="Enlace permanente a &quot;Aprende el mundo en lugar de seguir una combinación fija&quot;">​</a></h2><p>Un instructor, un libro, unas ruinas o una cultura desconocida pueden enseñarte algo que una cifra de habilidad no ofrece. Skill es habilidad o capacidad; <a href="/Syrolands-Public/es/guide/characters/techniques.html">Technique</a> es una técnica aprendida; Familiarity es fluidez práctica; <a href="/Syrolands-Public/es/guide/glossary.html#mastery">Mastery</a> es dominio profundo. Puedes especializarte sin esperar que el máximo de una habilidad revele todos los descubrimientos.</p><h2 id="professions-are-part-of-your-character-not-an-alt" tabindex="-1">Las profesiones forman parte de tu personaje, no de un personaje alternativo <a class="header-anchor" href="#professions-are-part-of-your-character-not-an-alt" aria-label="Enlace permanente a &quot;Las profesiones forman parte de tu personaje, no de un personaje alternativo&quot;">​</a></h2><p>Lleva Cooking a una expedición, Alchemy a un encuentro difícil o Blacksmithing a un equipo dañado. Tailoring, Carpentry y Tinkering también tienen usos más allá de vender productos. La artesanía interactiva, las técnicas, la experimentación y la reputación deberían integrar la profesión en la identidad del aventurero, sin prohibir personajes dedicados a fabricar.</p><h2 id="magic-is-knowledge-you-prepare-and-practice" tabindex="-1">La magia es conocimiento que preparas y practicas <a class="header-anchor" href="#magic-is-knowledge-you-prepare-and-practice" aria-label="Enlace permanente a &quot;La magia es conocimiento que preparas y practicas&quot;">​</a></h2><p>Aprende un <a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Core Pattern</a>, la estructura base de un hechizo, practícalo y elige qué patrones mantener en Active Memory, tu memoria preparada. Un hechizo preparado todavía necesita lanzarse. Los libros, los pergaminos y los reactivos ofrecen formas distintas de llevar, consultar y utilizar conocimiento mágico; Inscription lo conserva y modifica.</p><h2 id="objects-have-history-and-identity" tabindex="-1">Los objetos tienen historia e identidad <a class="header-anchor" href="#objects-have-history-and-identity" aria-label="Enlace permanente a &quot;Los objetos tienen historia e identidad&quot;">​</a></h2><p>Una herramienta fiable o un arma equilibrada pueden importar sin limitarse a aumentar el daño. El manejo, la consistencia y la conservación de su estado determinan su utilidad. Los <a href="/Syrolands-Public/es/guide/items/item-quality.html">Masterworks</a> representan logros artesanales excepcionales; las <a href="/Syrolands-Public/es/guide/items/item-quality.html">propiedades latentes</a> son posibles descubrimientos, no una promesa de que todo objeto excepcional se vuelva mágico.</p><h2 id="there-is-no-single-endgame" tabindex="-1">No existe una única meta final <a class="header-anchor" href="#there-is-no-single-endgame" aria-label="Enlace permanente a &quot;No existe una única meta final&quot;">​</a></h2><p>Hazte un nombre como duelista, explorador, artesano especialista, proveedor de confianza u organizador de una comunidad. El conocimiento, las relaciones económicas, la influencia social y la reputación pueden ser metas por sí mismas.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Llevas Carpentry a una expedición por el bosque. Un cruce bloqueado se convierte en un problema que tus herramientas y conocimientos podrían ayudar a resolver, mientras un compañero vigila el camino. Tu profesión contribuye a la misma aventura que tus decisiones de combate.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/glossary.html">Glosario</a> · <a href="/Syrolands-Public/es/guide/">Guía del jugador</a> · <a href="/Syrolands-Public/es/guide/combat/overview.html">Combate</a> · <a href="/Syrolands-Public/es/guide/world/living-world.html">Mundo vivo</a></p><h2 id="full-design-specification" tabindex="-1">Especificación completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/vision.html">Especificaciones de diseño: visión del proyecto</a></p>',29)])])}const h=a(r,[["render",t]]);export{p as __pageData,h as default};
